const questions = [
  {
    id: 1,
    question: "Which of the following are low-level programming languages?",
    helpText: "Low-level languages provide little or no abstraction from a computer's instruction set architecture.",
    options: ["Assembly", "Machine Code", "C", "Python"]
  },
  {
    id: 2,
    question: "Which of the following languages are commonly used for web development?",
    options: ["JavaScript", "HTML", "CSS", "COBOL"]
  },
  {
    id: 3,
    question: "Which of the following are functional programming languages?",
    options: ["Haskell", "Lisp", "Java", "Erlang"]
  }
];

const FormField = ({ id, question, options, helpText, selectedOptions, onToggle }) => {
  const helpId = `help-${id}`;
  return (
    <div className="form-field">
      <fieldset style={{ border: 'none', padding: 0, margin: 0 }}>
        <legend className="question-text">{question}</legend>
        {helpText && <div id={helpId} className="help-text">{helpText}</div>}
        <div className="options-group">
          {options.map(option => (
            <label key={option} className="option-item">
              <input
                type="checkbox"
                checked={selectedOptions.includes(option)}
                onChange={() => onToggle(option)}
                aria-describedby={helpText ? helpId : undefined}
              />
              <span>{option}</span>
            </label>
          ))}
        </div>
      </fieldset>
    </div>
  );
};

const Quiz = () => {
  const [selections, setSelections] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (questionId, option) => {
    setSelections(prev => {
      const current = prev[questionId] || [];
      const next = current.includes(option)
        ? current.filter(o => o !== option)
        : [...current, option];
      return { ...prev, [questionId]: next };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div className="quiz-container">
      <h1>Computer Languages Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map(q => (
          <FormField
            key={q.id}
            question={q.question}
            helpText={q.helpText}
            options={q.options}
            selectedOptions={selections[q.id] || []}
            onToggle={(option) => handleToggle(q.id, option)}
          />
        ))}
        <button type="submit" className="submit-btn">Submit Answers</button>
      </form>
      {submitted && (
        <div className="results">
          <strong>Thank you for completing the quiz!</strong>
          <p>You selected: {Object.values(selections).flat().join(", ") || "nothing"}</p>
        </div>
      )}
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('app'));
root.render(<Quiz />);
