31.             <label key={option} className="option-item">
32.               <input
33.                 type="checkbox"
34.                 checked={selectedOptions.includes(option)}
35.                 onChange={() => onToggle(option)}
36.                 aria-describedby={helpText ? helpId : undefined}
37.               />
